# save as: highres_topdown_export.py
"""
High-res top-down viewer + saver for AI2-THOR ProcTHOR / Objaverse houses.

What this script does:
- Loads houses from your Objaverse houses jsonl.gz split via prior.load_dataset
- Initializes StretchController at HIGH render resolution
- Calls controller.get_top_down_path_view(agent_path=...)
- Displays the top-down image
- Saves the RAW returned image (best quality) + an optional matplotlib figure

Run:
  python highres_topdown_export.py --house 152 --split val --outdir topdowns --res 4096 --show
Batch:
  python highres_topdown_export.py --start 0 --count 50 --split val --outdir topdowns --res 4096
"""

import os
import math
import argparse
from os import path
import numpy as np
import prior

import matplotlib.pyplot as plt
from matplotlib.patches import Circle
import imageio.v2 as imageio

from environment.stretch_controller import StretchController
from utils.constants.stretch_initialization_utils import STRETCH_ENV_ARGS
from utils.constants.objaverse_data_dirs import OBJAVERSE_HOUSES_DIR


# -------------------------
# Helpers
# -------------------------
def generate_circular_path(center_x, center_z, radius, num_points, y=0.9):
    path = []
    for i in range(num_points):
        theta = 2.0 * math.pi * i / max(1, num_points)
        x = center_x + radius * math.cos(theta)
        z = center_z + radius * math.sin(theta)
        path.append({"x": float(x), "y": float(y), "z": float(z)})
    return path


def remove_objects_by_id(house_dict, ids_to_remove):
    ids_to_remove = set(ids_to_remove)
    house_dict = dict(house_dict)  # shallow copy
    new_objs = []
    for o in house_dict.get("objects", []):
        if o.get("id") in ids_to_remove:
            continue
        new_objs.append(o)
    house_dict["objects"] = new_objs
    return house_dict


def remove_windows_by_id(house_dict, ids_to_remove):
    ids_to_remove = set(ids_to_remove)
    house_dict = dict(house_dict)
    house_dict["windows"] = [
        w for w in house_dict.get("windows", []) if w.get("id") not in ids_to_remove
    ]
    return house_dict


def load_houses(split: str):
    split = split.lower()
    assert split in ("train", "val", "test")
    ds = prior.load_dataset(
        dataset="spoc-data",
        entity="spoc-robot",
        revision="local-objaverse-procthor-houses",
        path_to_splits=None,
        split_to_path={
            k: os.path.join(OBJAVERSE_HOUSES_DIR, f"{k}.jsonl.gz")
            for k in ["train", "val", "test"]
        },
        max_houses_per_split=int(1e9),
    )
    return list(ds[split])


def init_controller_for_house(house_dict, res: int, timeout_s: int):
    """
    Initialize StretchController with HIGH render resolution.
    """
    controller_args = STRETCH_ENV_ARGS.copy()
    controller_args["renderInstanceSegmentation"] = False
    controller_args["server_timeout"] = int(timeout_s)

    # High-res render size (this is the key)
    controller_args["width"] = int(res)
    controller_args["height"] = int(res)

    ctrl = StretchController(scene=house_dict, **controller_args)
    return ctrl


def choose_center_for_path(house_dict, fallback=(1.5, 7.5)):
    """
    Try to pick a reasonable center location from rooms.
    If rooms exist: use centroid of the largest room's floor polygon in XZ.
    Otherwise fallback.
    """
    rooms = house_dict.get("rooms", [])
    best_area = -1.0
    best_center = None

    def poly_area_xz(poly):
        # poly: list of dicts with x,z
        if not poly or len(poly) < 3:
            return 0.0
        xs = np.array([p["x"] for p in poly], dtype=np.float64)
        zs = np.array([p["z"] for p in poly], dtype=np.float64)
        return 0.5 * float(np.abs(np.dot(xs, np.roll(zs, -1)) - np.dot(zs, np.roll(xs, -1))))

    for r in rooms:
        fp = r.get("floorPolygon", None)
        if not fp:
            continue
        a = poly_area_xz(fp)
        if a > best_area:
            best_area = a
            xs = np.array([p["x"] for p in fp], dtype=np.float64)
            zs = np.array([p["z"] for p in fp], dtype=np.float64)
            best_center = (float(xs.mean()), float(zs.mean()))

    if best_center is None:
        return (float(fallback[0]), float(fallback[1]))
    return best_center


